package com.tracksphere.infrastructure.security;
import com.tracksphere.domain.repository.UserRepository; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.util.*;
@Component @RequiredArgsConstructor public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwtService; private final UserRepository users; @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,java.io.IOException { String header=req.getHeader("Authorization"); if(header!=null&&header.startsWith("Bearer ")) try { UUID id=UUID.fromString(jwtService.subject(header.substring(7))); users.findById(id).filter(u->u.isEnabled()).ifPresent(u->{var authorities=u.getRoles().stream().map(r->new SimpleGrantedAuthority(r.getName())).toList(); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getId(),null,authorities));}); } catch(JwtException|IllegalArgumentException ignored){} chain.doFilter(req,res); } }
